+		return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
+	}
+	outputResolved, err := resolvedOutputPath(output)
+	if err != nil {
+		return err
+	}
+	brainResolved, err := filepath.EvalSymlinks(brainDir)
+	if err != nil {
+		brainResolved = brainAbs
