+		var record semanticRecord
+		if err := json.Unmarshal(text, &record); err != nil {
+			return semanticHeader{}, semanticCounts{}, fmt.Errorf("parse semantic snapshot line %d: %w", line, err)
+		}
+		switch record.RecordType {
+		case "symbol":
+			counts.Symbols++
+		case "relation":
+			counts.Relations++
