   694	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
   695		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
   696		if err != nil {
   697			return staleReport{}, err
   698		}
   699		if !local {
   700			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
   701		}
   702		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
   703		if err != nil {
   704			return staleReport{}, err
   705		}
   706		manifest, err := loadBrainManifest(storage.BrainDir)
   707		if err != nil {
   708			return staleReport{}, err
   709		}
   710		axes := map[string]staleAxis{}
   711		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
   712			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
   713			return staleReport{Severity: "unsafe", Axes: axes}, nil
   714		}
   715		source := manifest.Sources.Semantic
   716		if source.SnapshotPath == "" {
   717			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
   718		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
   719			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
   720		} else {
   721			snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
   722			snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)
   723			if snapshotErr != nil {
   724				axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
   725			} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
   726				axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
   727			} else {
   728				axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
   729			}
   730		}
   731		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
   732		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
   733		dirty := worktreeDirty(ctx, opts.Runner, repoDir)
   734		if source.Commit == head {
   735			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
   736		} else {
   737			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
   738		}
   739		if source.Branch == "" || source.Branch == branch {
   740			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
   741		} else {
   742			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
   743		}
   744		switch {
   745		case dirty && source.WorktreeMode != "worktree":
   746			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
   747		case dirty && source.WorktreeHash != "" && source.WorktreeHash != worktreeFingerprint(ctx, opts.Runner, repoDir):
   748			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
   749		case dirty:
   750			axes["worktree"] = staleAxis{State: "dirty-indexed"}
   751		case source.WorktreeMode == "worktree":
   752			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
   753		default:
   754			axes["worktree"] = staleAxis{State: "clean"}
   755		}
   756		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
   757			axes["provider"] = staleAxis{State: "degraded", Detail: "semantic provider was skipped"}
   758		} else if err := validateSemanticSchema(source.SchemaVersion); err != nil {
   759			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
   760		} else if !source.NoEgressVerified {
   761			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
   762		} else {
   763			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
   764		}
   765		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
   766			axes["semantic_completeness"] = staleAxis{State: "unsafe", Detail: "semantic facts unavailable"}
   767		} else if len(source.PartialFailures) > 0 {
   768			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
   769		} else {
   770			axes["semantic_completeness"] = staleAxis{State: "ok"}
   771		}
   772		severity := aggregateStaleSeverity(axes)
   773		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
   774	}
