   888			if first {
   889				first = false
   890				continue
   891			}
   892			var record semanticRecord
   893			if err := json.Unmarshal(scanner.Bytes(), &record); err != nil {
   894				return nil, err
   895			}
   896			if record.RecordType != "symbol" {
