  1003	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
  1004		value = strings.TrimSpace(value)
  1005		if strings.HasSuffix(value, "d") {
  1006			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
  1007			if err != nil || days < 0 {
  1008				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1009			}
  1010			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1011		}
  1012		duration, err := time.ParseDuration(value)
  1013		if err != nil {
  1014			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1015		}
  1016		return now.Add(-duration), nil
  1017	}
