  1186	func rejectSymlinkPathComponents(root, rel string) error {
  1187		clean := filepath.Clean(rel)
  1188		if filepath.IsAbs(clean) || clean == "." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
  1189			return fmt.Errorf("path is outside root: %s", rel)
  1190		}
  1191		current := root
  1192		for _, part := range strings.Split(clean, string(filepath.Separator)) {
  1193			current = filepath.Join(current, part)
  1194			info, err := os.Lstat(current)
  1195			if err != nil {
  1196				return err
  1197			}
  1198			if info.Mode()&os.ModeSymlink != 0 {
  1199				return fmt.Errorf("path component must not be a symlink: %s", rel)
  1200			}
  1201		}
  1202		rootResolved, err := filepath.EvalSymlinks(root)
  1203		if err != nil {
  1204			return err
  1205		}
  1206		pathResolved, err := filepath.EvalSymlinks(filepath.Join(root, clean))
  1207		if err != nil {
  1208			return err
  1209		}
  1210		if !pathInside(rootResolved, pathResolved) {
  1211			return fmt.Errorf("path escapes root through symlinks: %s", rel)
  1212		}
  1213		return nil
  1214	}
