  1216	func rejectBundleOutputInsideBrain(output, brainDir string) error {
  1217		outputAbs, err := filepath.Abs(output)
  1218		if err != nil {
  1219			return err
  1220		}
  1221		brainAbs, err := filepath.Abs(brainDir)
  1222		if err != nil {
  1223			return err
  1224		}
  1225		if pathInside(brainAbs, outputAbs) {
