  1227		}
  1228		outputResolved, err := resolvedOutputPath(output)
  1229		if err != nil {
  1230			return err
  1231		}
  1232		brainResolved, err := filepath.EvalSymlinks(brainDir)
  1233		if err != nil {
  1234			brainResolved = brainAbs
  1235		}
  1236		if pathInside(brainResolved, outputResolved) {
  1237			return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
  1238		}
  1239		return nil
  1240	}
