  1242	func pathInside(root, path string) bool {
  1243		rel, err := filepath.Rel(root, path)
  1244		if err != nil {
  1245			return false
  1246		}
  1247		return rel == "." || (!strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != "..")
  1248	}
