  1250	func resolvedOutputPath(output string) (string, error) {
  1251		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  1252			return filepath.Abs(resolved)
  1253		}
  1254		parent := filepath.Dir(output)
  1255		resolvedParent, err := filepath.EvalSymlinks(parent)
  1256		if err != nil {
  1257			resolvedParent, err = filepath.Abs(parent)
  1258			if err != nil {
  1259				return "", err
  1260			}
  1261		}
  1262		return filepath.Abs(filepath.Join(resolvedParent, filepath.Base(output)))
  1263	}
